insert into public.ppg_skill_domains
  (domain, label_th, label_en)
values
  ('Diagrams and Tables', 'แผนภาพและตาราง', 'Diagrams and Tables'),
  ('Motion and Animation', 'แอนิเมชันและการเคลื่อนไหว', 'Motion and Animation')
insert into public.ppg_modules
  (module_key, course_key, order_index, skill_domain, title_th, title_en, summary_th, summary_en, publication_state)
values
  ('chapter-07', 'presentation-program', 7, 'Diagrams and Tables', 'การแทรกแผนภาพและตารางในการนำเสนอ', 'Inserting diagrams and tables', 'ความหมายและรูปแบบของแผนภาพ SmartArt และแผนผังองค์กร และการสร้างตารางบนสไลด์', 'What a diagram is and its forms, SmartArt and organisation charts, and creating tables on a slide.', 'published'),
  ('chapter-08', 'presentation-program', 8, 'Motion and Animation', 'การตั้งค่าการเคลื่อนไหว', 'Setting motion', 'การเปลี่ยนสไลด์และเวลา แอนิเมชัน เส้นทางการเคลื่อนที่และทริกเกอร์ เอฟเฟกต์สำหรับแผนภูมิและ SmartArt และมัลติมีเดีย', 'Slide transitions and timing, animation effects, motion paths and triggers, effects for charts and SmartArt, and multimedia.', 'published')
insert into public.ppg_lessons
  (lesson_key, module_key, order_index, title_th, title_en, what_learn_th, what_learn_en, why_th, why_en, body_th, body_en, what_next_th, what_next_en, publication_state)
values
  ('chapter-07-lesson-01', 'chapter-07', 1, 'แผนภาพคืออะไรและมีรูปแบบบ้าง', 'What a diagram is, and its forms', 'อธิบายได้ว่าแผนภาพคืออะไรและเลือกรูปแบบที่เหมาะสมกับความคิดได้', 'Explain what a diagram is and choose a form that fits the idea.', 'แผนภาพเปลี่ยนความคิดนามธรรมให้เห็นความสัมพันธ์ได้เร็ว', 'A diagram turns an abstract idea into a relationship the audience can see quickly.', 'แผนภาพคือภาพที่ย่อความคิดหรือข้อมูลให้เหลือโครงสร้างหลัก เพื่อให้ผู้ฟังเห็นความสัมพันธ์ได้ในครั้งเดียว รูปแบบที่ใช้บ่อยคือลำดับขั้น กระบวนการ วัฏจักรและความสัมพันธ์ เลือกรูปแบบตามลักษณะของความคิด ไม่ใช่ตามความสวยงาม', 'A diagram is a picture that reduces an idea or data to its main structure, so the audience can see the relationship at a glance. The common forms are hierarchy, process, cycle, and relationship. Choose the form that matches the idea, not the one that looks prettiest.', 'ต่อไป: สร้างและแก้ไข SmartArt และแผนผังองค์กร', 'Next: creating and editing SmartArt and organisation charts.', 'published'),
  ('chapter-07-lesson-02', 'chapter-07', 2, 'SmartArt และแผนผังองค์กร: สร้างและแก้ไข', 'SmartArt and organisation charts: create and edit', 'แทรก SmartArt เพิ่มและลบรูปร่าง เลื่อนขึ้นหรือลดระดับ และสร้างแผนผังองค์กรได้', 'Insert SmartArt, add and remove shapes, promote or demote them, and build an organisation chart.', 'SmartArt ช่วยให้สร้างแผนภาพที่จัดวางอัตโนมัติโดยไม่ต้องวาดมือเอง', 'SmartArt builds an arranged diagram automatically instead of drawing every shape by hand.', 'SmartArt คือชุดแผนภาพพร้อมใช้ที่แทรกจากแท็บ Insert จากนั้นเลือกชนิด เช่นกระบวนการลำดับขั้นหรือวัฏจักร หลังแทรกจะมีกล่องข้อความให้พิมพ์ และมีคำสั่งเพิ่มรูปร่าง เลื่อนขึ้นลดระดับ และเปลี่ยนสี แผนผังองค์กรคือ SmartArt ชนิดลำดับขั้นที่ใช้แสดงสายงานและผู้รับผิดชอบ', 'SmartArt is a set of ready-made diagrams you insert from the Insert tab and then pick a type such as process, hierarchy, or cycle. After you insert it, a text box lets you type, and commands add a shape, promote, demote, and change the colour. An organisation chart is a hierarchy SmartArt used to show reporting lines and who is responsible.', 'ต่อไป: สร้างตารางบนสไลด์', 'Next: creating tables on slides.', 'published'),
  ('chapter-07-lesson-03', 'chapter-07', 3, 'การสร้างตารางบนสไลด์', 'Creating tables on slides', 'แทรกตาราง ตั้งจำนวนแถวและคอลัมน์ และแก้ไขเซลล์ได้', 'Insert a table, set the number of rows and columns, and edit cells.', 'ตารางจัดวางข้อมูลให้เดียวกันและเปรียบเทียบได้ง่าย', 'A table lines data up so it is easy to compare.', 'ตารางใช้เมื่อต้องแสดงข้อมูลหลายค่าที่ต้องเปรียบเทียบกันเช่นราคา จำนวน หรือกำหนดเวลา แทรกตารางจากแท็บ Insert เลือกตารางจากนั้นลากช่องหรือพิมพ์จำนวนแถวและคอลัมน์ แตละช่องเรียกว่าเซลล์ ใช้แท็บ Table Design และ Layout เพื่อเพิ่มหรือลบแถวและคอลัมน์ รวมเซลล์และเลือกสีตาราง', 'Use a table when you must show several values that need comparing, such as price, quantity, or schedule. Insert a table from the Insert tab: choose Table, then drag over the grid or type the number of rows and columns. Each box is a cell. Use the Table Design and Layout tabs to add or remove rows and columns, merge cells, and choose a table colour.', 'ต่อไป: ภารกิจความรู้และข้อสอบหลังเรียน', 'Next: the Knowledge Mission and the chapter post-test.', 'published'),
  ('chapter-08-lesson-01', 'chapter-08', 1, 'การเปลี่ยนสไลด์และการตั้งเวลา', 'Slide transitions and timing', 'ใส่การเปลี่ยนสไลด์ ตั้งระยะเวลา และเลือกแบบที่เหมาะสมได้', 'Apply a slide transition, set its duration, and choose a transition that fits.', 'การเปลี่ยนสไลด์ที่เหมาะสมช่วยให้ผู้ฟังตามเรื่องโดยไม่สะดุด', 'A fitting transition helps the audience follow the story without stumbling.', 'การเปลี่ยนสไลด์คือเอฟเฟกต์ที่เกิดเมื่อเปลี่ยนจากสไลด์หนึ่งไปยังสไลด์อื่น ใส่จากแท็บ Transitions จากนั้นเลือกจากแกลเลอรี ตั้งระยะเวลา และเลือกที่จะเปลี่ยนเมื่อคลิกหรืออัตโนมัติ ใช้การเปลี่ยนสไลด์แบบเดียวทั้งชุดและไม่ยาวมากเกินไปเพื่อให้ไม่รบกวนเนื้อหา', 'A slide transition is the effect that plays when one slide changes to the next. Apply it from the Transitions tab, pick one from the gallery, set the duration, and choose whether it runs on click or automatically. Use one transition for the whole deck and keep it short so it does not distract from the content.', 'ต่อไป: แอนิเมชันเส้นทางการเคลื่อนที่และทริกเกอร์', 'Next: animation effects, motion paths, and triggers.', 'published'),
  ('chapter-08-lesson-02', 'chapter-08', 2, 'แอนิเมชัน เส้นทางการเคลื่อนที่ และทริกเกอร์', 'Animation effects, motion paths, and triggers', 'เพิ่มแอนิเมชัน เลือกทางเข้า ทางออก และการเน้น และตั้งทริกเกอร์ได้', 'Add an animation, choose entrance, exit, or emphasis, and set a trigger.', 'แอนิเมชันที่เหมาะสมช่วยให้ผู้ฟังเห็นลำดับของความคิด', 'A fitting animation helps the audience see the order of the ideas.', 'แอนิเมชันคือเอฟเฟกต์ที่เกิดกับวัตถุบนสไลด์เช่นข้อความ ภาพ หรือแผนภูมิ มีสามกลุ่มคือทางเข้า ทางออก และการเน้น ใส่จากแท็บ Animations จากนั้นใช้ Animation Pane จัดวางลำดับ ตั้งให้เริ่มเมื่อคลิก พร้อมกัน หรือหลังรายการก่อนหน้า เส้นทางการเคลื่อนที่ทำให้วัตถุย้ายตามเส้นทางและทริกเกอร์ทำให้เอฟเฟกต์เริ่มเมื่อเกิดเหตุการณ์ เช่นคลิกวัตถุหนึ่ง', 'An animation is an effect applied to an object on a slide, such as text, a picture, or a chart. There are three groups: entrance, exit, and emphasis. Add it from the Animations tab, use the Animation Pane to order it, and set it to start on click, together with the previous item, or after the previous item. A motion path moves an object along a line, and a trigger starts an effect on an event such as clicking another object.', 'ต่อไป: เอฟเฟกต์สำหรับแผนภูมิ SmartArt และมัลติมีเดีย', 'Next: effects for charts, SmartArt, and organisation charts, plus multimedia.', 'published'),
  ('chapter-08-lesson-03', 'chapter-08', 3, 'เอฟเฟกต์สำหรับแผนภูมิ SmartArt และแผนผังองค์กร เทคนิคพิเศษและมัลติมีเดีย', 'Effects for charts, SmartArt, and organisation charts; special techniques and multimedia', 'เพิ่มแอนิเมชันในแผนภูมิและ SmartArt แทรกเสียงหรือวิดีโอ และตั้งการเล่นได้', 'Animate charts and SmartArt, insert audio or video, and set how it plays.', 'มัลติมีเดียที่เหมาะสมช่วยอธิบายให้ชัดเจนแต่ที่มากเกินไปรบกวนผู้ฟัง', 'Fitting multimedia explains more clearly, but too much of it distracts the audience.', 'แผนภูมิและ SmartArt มีแอนิเมชันเฉพาะ เช่นให้ชุดข้อมูลเข้าทีละรายการ หรือให้แตละสาขาของแผนผังองค์กรปรากฏตามลำดับ ใช้ตัวเลือกเอฟเฟกต์เลือกวิธีนี้ แทรกเสียงหรือวิดีโอจากแท็บ Insert จากนั้นตั้งการเล่นอัตโนมัติหรือเมื่อคลิก ใช้เสียงบรรยายเมื่อสอนออนไลน์และปิดเสียงเมื่อไม่จำเป็น', 'Charts and SmartArt have their own animation options, such as bringing each series in one by one or revealing each branch of an organisation chart in order. Use Effect Options to choose this. Insert audio or video from the Insert tab, then set it to play automatically or on click. Use narration when you teach online, and mute the sound when you do not need it.', 'ต่อไป: ภารกิจความรู้และข้อสอบหลังเรียน', 'Next: the Knowledge Mission and the chapter post-test.', 'published')
insert into public.ppg_lesson_steps
  (lesson_key, order_index, kind, body_th, body_en, check_prompt_th, check_prompt_en, check_answer_key, check_explanation_th, check_explanation_en)
values
  ('chapter-07-lesson-01', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะอธิบายความหมายของแผนภาพและเลือกรูปแบบที่เหมาะสมได้', 'By the end you can explain what a diagram is and choose a suitable form.', null, null, null, null, null),
  ('chapter-07-lesson-01', 2, 'explanation', 'แผนภาพใช้เมื่อความคิดมีความสัมพันธ์เช่นลำดับ วัฏจักรหรือโครงสร้าง', 'Use a diagram when the ideas have a relationship, such as order, a cycle, or a structure.', null, null, null, null, null),
  ('chapter-07-lesson-01', 3, 'example', 'ตัวอย่างทีมขายใช้แผนภาพกระบวนการห้าขั้นตอนอธิบายการอนุมัติสินเชื่อ', 'Example: the sales team uses a five-step process diagram to explain loan approval.', null, null, null, null, null),
  ('chapter-07-lesson-01', 4, 'explanation', 'เลือกรูปแบบตามความสัมพันธ์ ไม่ใช่ตามความสวยงาม ถ้าเป็นลำดับให้ใช้กระบวนการ ถ้าเป็นวัฏจักรให้ใช้วัฏจักร', 'Choose the form by the relationship, not by looks: use a process for an order and a cycle for a loop.', null, null, null, null, null),
  ('chapter-07-lesson-01', 5, 'check', '', '', 'แผนภาพใดเหมาะสมกับความคิดที่เป็นวัฏจักร', 'Which diagram suits an idea that is a cycle?', 'b', 'วัฏจักรแสดงความคิดที่วนกลับที่เดิม กระบวนการแสดงลำดับที่จบ', 'A cycle shows ideas that loop back to the start; a process shows an order that ends.'),
  ('chapter-07-lesson-01', 6, 'summary', 'เลือกแผนภาพตรงกับความสัมพันธ์จากนั้นให้ผู้ฟังเห็นภาพได้ในครั้งเดียว', 'Match the diagram to the relationship, and let the audience see the picture at a glance.', null, null, null, null, null),
  ('chapter-07-lesson-02', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะสร้างและแก้ไข SmartArt กับแผนผังองค์กรได้', 'By the end you can create and edit SmartArt and an organisation chart.', null, null, null, null, null),
  ('chapter-07-lesson-02', 2, 'explanation', 'SmartArt เปลี่ยนรายการข้อความกลายเป็นแผนภาพจัดวางและเชื่อมรูปร่างให้เอง', 'SmartArt turns a text list into a diagram and arranges and connects the shapes for you.', null, null, null, null, null),
  ('chapter-07-lesson-02', 3, 'example', 'ตัวอย่างแผนกบุคคลใช้แผนผังองค์กรแสดงหัวหน้าและทีมในบริษัท', 'Example: the HR department uses an organisation chart to show the managers and teams in the company.', null, null, null, null, null),
  ('chapter-07-lesson-02', 4, 'explanation', 'เลือก SmartArt จากนั้นใช้กล่องข้อความพิมพ์รายการ ใช้เพิ่มรูปร่างเพื่อเพิ่มคน และใช้เลื่อนขึ้นหรือลดระดับจัดวางสายงาน', 'Select the SmartArt, type the list in the text box, use Add Shape to add a person, and promote or demote to arrange the reporting line.', null, null, null, null, null),
  ('chapter-07-lesson-02', 5, 'check', '', '', 'ต้องการเพิ่มตำแหน่งใต้ผู้จัดการในแผนผังองค์กรควรทำอย่างไร', 'You need to add a position under a manager in an organisation chart. What should you do?', 'a', 'เพิ่มรูปร่างไหม่จากนั้นลดระดับเพื่อให้อยู่ใต้ตำแหน่งที่เลือก', 'Add a new shape, then demote it so it sits under the selected position.'),
  ('chapter-07-lesson-02', 6, 'summary', 'SmartArt ทำให้แผนภาพเร็วและสม่ำเสมอแต่ยังต้องจัดวางลำดับขั้นให้ตรงกับสายงานจริง', 'SmartArt makes diagrams fast and consistent, but you still arrange the hierarchy to match the real reporting line.', null, null, null, null, null),
  ('chapter-07-lesson-03', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะแทรกตารางและแก้ไขแถวคอลัมน์และเซลล์ได้', 'By the end you can insert a table and edit its rows, columns, and cells.', null, null, null, null, null),
  ('chapter-07-lesson-03', 2, 'explanation', 'ตารางมีแถวแนวนอนและคอลัมน์แนวตั้ง จุดตัดคือเซลล์', 'A table has horizontal rows and vertical columns; where they meet is a cell.', null, null, null, null, null),
  ('chapter-07-lesson-03', 3, 'example', 'ตัวอย่างใบเสนอราคาใช้ตารางสามคอลัมน์คือรายการ จำนวนและราคา', 'Example: a quotation uses a three-column table for the item, quantity, and price.', null, null, null, null, null),
  ('chapter-07-lesson-03', 4, 'explanation', 'คลิกในเซลล์จากนั้นพิมพ์ข้อมูล ใช้แท็บ Layout เพิ่มแถวหรือคอลัมน์และใช้รวมเซลล์เมื่อต้องใช้ช่องกว้างขึ้น', 'Click a cell and type the data; use the Layout tab to add a row or column, and merge cells when you need a wider box.', null, null, null, null, null),
  ('chapter-07-lesson-03', 5, 'check', '', '', 'ต้องการรวมสองเซลล์ให้เป็นช่องเดียวควรใช้คำสั่งใด', 'You want to turn two cells into one. Which command do you use?', 'a', 'รวมเซลล์ทำให้สองช่องเป็นช่องเดียว เหมาะสมกับหัวตารางที่กินหลายคอลัมน์', 'Merge Cells turns two boxes into one; it suits a header that spans several columns.'),
  ('chapter-07-lesson-03', 6, 'summary', 'แทรกตารางให้พอดีกับข้อมูลใช้หัวตารางและเส้นขอบให้อ่านง่ายและรวมเซลล์เมื่อจำเป็น', 'Size the table to the data, use a clear header row and borders, and merge cells only when needed.', null, null, null, null, null),
  ('chapter-08-lesson-01', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะใส่การเปลี่ยนสไลด์และตั้งเวลาได้', 'By the end you can apply a slide transition and set its timing.', null, null, null, null, null),
  ('chapter-08-lesson-01', 2, 'explanation', 'การเปลี่ยนสไลด์มีผลกับทั้งสไลด์ ไม่ใช่กับวัตถุบนสไลด์', 'A transition affects the whole slide, not the objects on it.', null, null, null, null, null),
  ('chapter-08-lesson-01', 3, 'example', 'ตัวอย่างอบรมใช้การเปลี่ยนสไลด์แบบจางให้ทุกสไลด์เพื่อให้ไม่ดึงความสนใจ', 'Example: a training deck uses a fade on every slide so it does not pull attention away.', null, null, null, null, null),
  ('chapter-08-lesson-01', 4, 'explanation', 'ตั้งระยะเวลาให้สั้นเช่นครึ่งวินาทีและเลือกเปลี่ยนเมื่อคลิกเพื่อให้ผู้บรรยายควบคุมจังหวะ', 'Set a short duration, such as half a second, and change on click so the speaker controls the rhythm.', null, null, null, null, null),
  ('chapter-08-lesson-01', 5, 'check', '', '', 'การเปลี่ยนสไลด์มีผลกับอะไร', 'What does a slide transition affect?', 'a', 'การเปลี่ยนสไลด์เกิดกับทั้งสไลด์ ขณะที่แอนิเมชันเกิดกับวัตถุ', 'A transition acts on the whole slide, while an animation acts on an object.'),
  ('chapter-08-lesson-01', 6, 'summary', 'ใช้การเปลี่ยนสไลด์แบบเดียวทั้งชุดให้สั้นและสม่ำเสมอเพื่อให้ให้เนื้อหาเด่น', 'Use one transition for the whole deck, keep it short and consistent, and let the content stand out.', null, null, null, null, null),
  ('chapter-08-lesson-02', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะเพิ่มแอนิเมชันและตั้งทริกเกอร์ได้', 'By the end you can add an animation and set a trigger.', null, null, null, null, null),
  ('chapter-08-lesson-02', 2, 'explanation', 'ทางเข้าทำให้วัตถุปรากฏ ทางออกทำให้วัตถุหายและการเน้นดึงสายตาขณะที่วัตถุยังอยู่', 'Entrance makes an object appear, exit makes it disappear, and emphasis pulls the eye while the object stays.', null, null, null, null, null),
  ('chapter-08-lesson-02', 3, 'example', 'ตัวอย่างรายงานความก้าวหน้าให้ตัวเลขยอดขายเข้าทีละรายการเพื่อให้ผู้ฟังเห็นประเด็น', 'Example: the progress report brings the sales figures in one by one so the audience sees the point.', null, null, null, null, null),
  ('chapter-08-lesson-02', 4, 'explanation', 'ใช้ Animation Pane จัดวางลำดับตั้งให้เริ่มแบบเมื่อคลิกพร้อมกันหรือหลังรายการก่อนหน้าและใช้เส้นทางการเคลื่อนที่ให้วัตถุย้ายตามเส้นทาง', 'Use the Animation Pane to order effects, set Start to On Click, With Previous, or After Previous, and use a motion path to move an object along a line.', null, null, null, null, null),
  ('chapter-08-lesson-02', 5, 'check', '', '', 'เอฟเฟกต์ใดทำให้วัตถุหายจากสไลด์', 'Which effect makes an object disappear from the slide?', 'b', 'ทางออกทำให้วัตถุหาย ขณะที่ทางเข้าทำให้ปรากฏและการเน้นดึงสายตา', 'Exit makes the object disappear; entrance makes it appear and emphasis pulls the eye.'),
  ('chapter-08-lesson-02', 6, 'summary', 'ใช้แอนิเมชันน้อยแต่ตรงกับจังหวะตั้งทริกเกอร์เมื่อจำเป็นและตรวจลำดับใน Animation Pane', 'Use few animations but the right rhythm, set a trigger only when needed, and check the order in the Animation Pane.', null, null, null, null, null),
  ('chapter-08-lesson-03', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะเพิ่มเอฟเฟกต์ให้แผนภูมิและ SmartArt และใช้มัลติมีเดียได้', 'By the end you can animate charts and SmartArt and use multimedia.', null, null, null, null, null),
  ('chapter-08-lesson-03', 2, 'explanation', 'ตัวเลือกเอฟเฟกต์เปลี่ยนวิธีที่ชุดข้อมูลหรือสาขาปรากฏเช่นทีละรายการหรือตามหมวด', 'Effect Options changes the way a series or branch appears, such as one by one or by category.', null, null, null, null, null),
  ('chapter-08-lesson-03', 3, 'example', 'ตัวอย่างสไลด์แนะนำบริษัทให้แตละสาขาของแผนผังองค์กรเข้าตามลำดับจากบนลงล่าง', 'Example: the company introduction slide brings each branch of the organisation chart in top to bottom.', null, null, null, null, null),
  ('chapter-08-lesson-03', 4, 'explanation', 'แทรกเสียงหรือวิดีโอจากแท็บ Insert ตั้งให้เล่นอัตโนมัติหรือเมื่อคลิกและตัดส่วนที่ไม่ต้องการได้', 'Insert audio or video from the Insert tab, set it to play automatically or on click, and trim the parts you do not need.', null, null, null, null, null),
  ('chapter-08-lesson-03', 5, 'check', '', '', 'ต้องการให้แตละชุดข้อมูลของแผนภูมิเข้าทีละรายการควรทำอย่างไร', 'You want each series of a chart to come in one by one. What should you do?', 'a', 'ตัวเลือกเอฟเฟกต์ตั้งให้ชุดข้อมูลเข้าทีละรายการหรือตามหมวด', 'Effect Options sets the series to come in one by one or by category.'),
  ('chapter-08-lesson-03', 6, 'summary', 'ใช้เอฟเฟกต์และมัลติมีเดียเพื่ออธิบาย ไม่ใช่เพื่อความตื่นเต้นและปิดเสียงเมื่อไม่จำเป็น', 'Use effects and multimedia to explain, not to excite, and mute the sound when it is not needed.', null, null, null, null, null)
