insert into public.ppg_knowledge_missions
  (module_key, instructions_th, instructions_en)
values
  ('chapter-07', 'ภารกิจความรู้: ตอบคำถามหกข้อเกี่ยวกับแผนภาพ SmartArt และตารางผ่านที่ 70%และทำซ้ำได้ไม่จำกัด', 'Knowledge Mission: answer six questions about diagrams, SmartArt, and tables. 70% passes; you can retry without limit.'),
  ('chapter-08', 'ภารกิจความรู้: ตอบคำถามหกข้อเกี่ยวกับการเปลี่ยนสไลด์ แอนิเมชันและมัลติมีเดียผ่านที่ 70%และทำซ้ำได้ไม่จำกัด', 'Knowledge Mission: answer six questions about transitions, animation, and multimedia. 70% passes; you can retry without limit.')
insert into public.ppg_knowledge_mission_questions
  (module_key, order_index, option_key, prompt_th, prompt_en, option_th, option_en, is_correct, explanation_th, explanation_en, review_th, review_en)
values
  ('chapter-07', 1, 'a', 'แผนภาพเหมาะสมสำหรับงานใด', 'What is a diagram good for?', 'แสดงความสัมพันธ์และโครงสร้างให้เห็นเร็ว', 'Showing relationships and structure at a glance', true, 'แผนภาพเปลี่ยนความคิดหรือข้อมูลให้เห็นความสัมพันธ์เร็วกว่าข้อความยาว', 'A diagram turns an idea or data into a relationship that is faster to see than long text.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-07', 1, 'b', 'แผนภาพเหมาะสมสำหรับงานใด', 'What is a diagram good for?', 'อธิบายข้อความยาว', 'Giving a long written explanation', false, 'แผนภาพเปลี่ยนความคิดหรือข้อมูลให้เห็นความสัมพันธ์เร็วกว่าข้อความยาว', 'A diagram turns an idea or data into a relationship that is faster to see than long text.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-07', 1, 'c', 'แผนภาพเหมาะสมสำหรับงานใด', 'What is a diagram good for?', 'รายการแหล่งข้อมูล', 'Listing the sources of the data', false, 'แผนภาพเปลี่ยนความคิดหรือข้อมูลให้เห็นความสัมพันธ์เร็วกว่าข้อความยาว', 'A diagram turns an idea or data into a relationship that is faster to see than long text.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-07', 2, 'a', 'รูปแบบใดเหมาะสมสำหรับแสดงสายงาน', 'Which form suits showing reporting lines?', 'วัฏจักร', 'A cycle', false, 'ลำดับขั้นแสดงตำแหน่งและสายงาน วัฏจักรแสดงความคิดที่วนกลับ กระบวนการแสดงลำดับของขั้นตอน', 'A hierarchy shows positions and reporting lines; a cycle shows a loop and a process shows steps.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-07', 2, 'b', 'รูปแบบใดเหมาะสมสำหรับแสดงสายงาน', 'Which form suits showing reporting lines?', 'ลำดับขั้น', 'A hierarchy', true, 'ลำดับขั้นแสดงตำแหน่งและสายงาน วัฏจักรแสดงความคิดที่วนกลับ กระบวนการแสดงลำดับของขั้นตอน', 'A hierarchy shows positions and reporting lines; a cycle shows a loop and a process shows steps.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-07', 2, 'c', 'รูปแบบใดเหมาะสมสำหรับแสดงสายงาน', 'Which form suits showing reporting lines?', 'กระบวนการ', 'A process', false, 'ลำดับขั้นแสดงตำแหน่งและสายงาน วัฏจักรแสดงความคิดที่วนกลับ กระบวนการแสดงลำดับของขั้นตอน', 'A hierarchy shows positions and reporting lines; a cycle shows a loop and a process shows steps.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-07', 3, 'a', 'แทรก SmartArt จากแท็บใด', 'From which tab do you insert SmartArt?', 'แท็บ Insert', 'The Insert tab', true, 'SmartArt แทรกจากแท็บ Insert จากนั้นเลือกชนิดแผนภาพ', 'Insert SmartArt from the Insert tab, then choose the diagram type.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-07', 3, 'b', 'แทรก SmartArt จากแท็บใด', 'From which tab do you insert SmartArt?', 'แท็บ Home', 'The Home tab', false, 'SmartArt แทรกจากแท็บ Insert จากนั้นเลือกชนิดแผนภาพ', 'Insert SmartArt from the Insert tab, then choose the diagram type.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-07', 3, 'c', 'แทรก SmartArt จากแท็บใด', 'From which tab do you insert SmartArt?', 'แท็บ Slide Show', 'The Slide Show tab', false, 'SmartArt แทรกจากแท็บ Insert จากนั้นเลือกชนิดแผนภาพ', 'Insert SmartArt from the Insert tab, then choose the diagram type.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-07', 4, 'a', 'คำสั่งใดทำให้ตำแหน่งไหม่อยู่ใต้ตำแหน่งที่เลือก', 'Which command puts a new position under the selected one?', 'ลดระดับ', 'Demote', true, 'ลดระดับทำให้ตำแหน่งไหม่อยู่ใต้ตำแหน่งที่เลือก เลื่อนขึ้นทำให้ไปขึ้นหนึ่งระดับ', 'Demote moves a new position under the selected one; Promote moves it up one level.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-07', 4, 'b', 'คำสั่งใดทำให้ตำแหน่งไหม่อยู่ใต้ตำแหน่งที่เลือก', 'Which command puts a new position under the selected one?', 'เลื่อนขึ้น', 'Promote', false, 'ลดระดับทำให้ตำแหน่งไหม่อยู่ใต้ตำแหน่งที่เลือก เลื่อนขึ้นทำให้ไปขึ้นหนึ่งระดับ', 'Demote moves a new position under the selected one; Promote moves it up one level.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-07', 4, 'c', 'คำสั่งใดทำให้ตำแหน่งไหม่อยู่ใต้ตำแหน่งที่เลือก', 'Which command puts a new position under the selected one?', 'รวมเซลล์', 'Merge Cells', false, 'ลดระดับทำให้ตำแหน่งไหม่อยู่ใต้ตำแหน่งที่เลือก เลื่อนขึ้นทำให้ไปขึ้นหนึ่งระดับ', 'Demote moves a new position under the selected one; Promote moves it up one level.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-07', 5, 'a', 'แทรกตารางเริ่มจากที่ไหน', 'Where do you start when inserting a table?', 'แท็บ Insert จากนั้นตาราง', 'The Insert tab, then Table', true, 'ตารางแทรกจากแท็บ Insert เลือกตารางจากนั้นลากช่องหรือพิมพ์จำนวนแถวและคอลัมน์', 'Start at the Insert tab, choose Table, then drag the grid or type the row and column counts.', 'ทบทวนบทเรียนที่ 3', 'Review lesson 3'),
  ('chapter-07', 5, 'b', 'แทรกตารางเริ่มจากที่ไหน', 'Where do you start when inserting a table?', 'แท็บ Home จากนั้น Bold', 'The Home tab, then Bold', false, 'ตารางแทรกจากแท็บ Insert เลือกตารางจากนั้นลากช่องหรือพิมพ์จำนวนแถวและคอลัมน์', 'Start at the Insert tab, choose Table, then drag the grid or type the row and column counts.', 'ทบทวนบทเรียนที่ 3', 'Review lesson 3'),
  ('chapter-07', 5, 'c', 'แทรกตารางเริ่มจากที่ไหน', 'Where do you start when inserting a table?', 'แท็บ Insert จากนั้นแผนภูมิ', 'The Insert tab, then Chart', false, 'ตารางแทรกจากแท็บ Insert เลือกตารางจากนั้นลากช่องหรือพิมพ์จำนวนแถวและคอลัมน์', 'Start at the Insert tab, choose Table, then drag the grid or type the row and column counts.', 'ทบทวนบทเรียนที่ 3', 'Review lesson 3'),
  ('chapter-07', 6, 'a', 'คำสั่งใดรวมสองเซลล์ให้เป็นช่องเดียว', 'Which command turns two cells into one?', 'รวมเซลล์', 'Merge Cells', true, 'รวมเซลล์ทำให้สองเซลล์เป็นเซลล์เดียว แยกเซลล์ทำให้เซลล์หนึ่งเป็นหลายเซลล์', 'Merge Cells joins two cells into one; Split Cells does the reverse.', 'ทบทวนบทเรียนที่ 3', 'Review lesson 3'),
  ('chapter-07', 6, 'b', 'คำสั่งใดรวมสองเซลล์ให้เป็นช่องเดียว', 'Which command turns two cells into one?', 'แยกเซลล์', 'Split Cells', false, 'รวมเซลล์ทำให้สองเซลล์เป็นเซลล์เดียว แยกเซลล์ทำให้เซลล์หนึ่งเป็นหลายเซลล์', 'Merge Cells joins two cells into one; Split Cells does the reverse.', 'ทบทวนบทเรียนที่ 3', 'Review lesson 3'),
  ('chapter-07', 6, 'c', 'คำสั่งใดรวมสองเซลล์ให้เป็นช่องเดียว', 'Which command turns two cells into one?', 'ลบแถว', 'Delete Row', false, 'รวมเซลล์ทำให้สองเซลล์เป็นเซลล์เดียว แยกเซลล์ทำให้เซลล์หนึ่งเป็นหลายเซลล์', 'Merge Cells joins two cells into one; Split Cells does the reverse.', 'ทบทวนบทเรียนที่ 3', 'Review lesson 3'),
  ('chapter-08', 1, 'a', 'การเปลี่ยนสไลด์ช่วยอะไร', 'What does a slide transition help with?', 'ตามเรื่องโดยไม่สะดุด', 'Following the story without stumbling', true, 'การเปลี่ยนสไลด์ที่เหมาะสมช่วยผู้ฟังตามเรื่องโดยไม่สะดุด ไม่ต้องใช้แบบต่างกันทุกสไลด์', 'A fitting transition helps the audience follow the story; it does not need to differ on every slide.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-08', 1, 'b', 'การเปลี่ยนสไลด์ช่วยอะไร', 'What does a slide transition help with?', 'ทำให้ทุกสไลด์ต่างกัน', 'Making every slide different', false, 'การเปลี่ยนสไลด์ที่เหมาะสมช่วยผู้ฟังตามเรื่องโดยไม่สะดุด ไม่ต้องใช้แบบต่างกันทุกสไลด์', 'A fitting transition helps the audience follow the story; it does not need to differ on every slide.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-08', 1, 'c', 'การเปลี่ยนสไลด์ช่วยอะไร', 'What does a slide transition help with?', 'แทนที่เนื้อหา', 'Replacing the content', false, 'การเปลี่ยนสไลด์ที่เหมาะสมช่วยผู้ฟังตามเรื่องโดยไม่สะดุด ไม่ต้องใช้แบบต่างกันทุกสไลด์', 'A fitting transition helps the audience follow the story; it does not need to differ on every slide.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-08', 2, 'a', 'ควรตั้งระยะเวลาการเปลี่ยนสไลด์อย่างไร', 'How should you set the transition duration?', 'สั้นและพอดี', 'Short and fitting', true, 'ระยะเวลาสั้นช่วยผู้ฟังตามโดยไม่รบกวน ยาวมากเกินไปทำให้ผู้ฟังรอ', 'A short duration keeps the audience following; too long makes them wait.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-08', 2, 'b', 'ควรตั้งระยะเวลาการเปลี่ยนสไลด์อย่างไร', 'How should you set the transition duration?', 'ยาวมากที่สุด', 'As long as possible', false, 'ระยะเวลาสั้นช่วยผู้ฟังตามโดยไม่รบกวน ยาวมากเกินไปทำให้ผู้ฟังรอ', 'A short duration keeps the audience following; too long makes them wait.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-08', 2, 'c', 'ควรตั้งระยะเวลาการเปลี่ยนสไลด์อย่างไร', 'How should you set the transition duration?', 'สุ่มทุกสไลด์', 'Random on every slide', false, 'ระยะเวลาสั้นช่วยผู้ฟังตามโดยไม่รบกวน ยาวมากเกินไปทำให้ผู้ฟังรอ', 'A short duration keeps the audience following; too long makes them wait.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-08', 3, 'a', 'แอนิเมชันควรใช้เมื่อใด', 'When should you use an animation?', 'เมื่อช่วยเห็นลำดับของความคิด', 'When it helps the audience see the order of ideas', true, 'แอนิเมชันที่เหมาะสมช่วยผู้ฟังเห็นลำดับของความคิด ไม่ใช่เพื่อความตื่นเต้น', 'An animation earns its place when it shows the order of ideas, not just for excitement.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
